/**
 * ====================================================================
 *  Rust Tree CLI Utility for Windows
 *  Generated by Rust Tree Command Builder
 * ====================================================================
 * 
 *  このプログラムは、指定したディレクトリの構造をツリー形式で出力するCLIツールです。
 *  外部の重いライブラリ（clapなど）に依存せず、Rustの標準ライブラリ（std）のみで
 *  軽量・高速に動作するように記述されています。
 */

use std::env;
use std::fs;
use std::path::{Path, PathBuf};

/// ツールでサポートする設定オプション
#[derive(Debug, Clone)]
struct TreeConfig {
    target_path: PathBuf,
    show_icons: bool,
    show_sizes: bool,
    show_hidden: bool,
    max_depth: usize,
    exclude_patterns: Vec<String>,
}

impl Default for TreeConfig {
    fn default() -> Self {
        Self {
            target_path: PathBuf::from("."),
            show_icons: true,
            show_sizes: true,
            show_hidden: false,
            max_depth: 0,
            exclude_patterns: vec!["target", "node_modules", ".git"].into_iter().map(String::from).collect(),
        }
    }
}

fn main() {
    // Windows 10/11のプロンプトでANSIエスケープカラーを有効化
    #[cfg(windows)]
    enable_ansi_support();

    // 1. 引数の解析
    let args: Vec<String> = env::args().collect();
    let mut config = TreeConfig::default();

    if let Err(err) = parse_arguments(&args, &mut config) {
        eprintln!("【エラー】: {}", err);
        print_help();
        std::process::exit(1);
    }

    // ターゲットが存在するか検証
    if !config.target_path.exists() {
        eprintln!("【エラー】: 指定されたパスが存在しません: {:?}", config.target_path);
        std::process::exit(1);
    }

    // 2. ツリー出力の開始
    println!("{}", format_root_line(&config));

    let mut dir_count = 0;
    let mut file_count = 0;
    
    // 再帰的にツリーを描画
    print_tree(
        &config.target_path,
        0,
        &mut Vec::new(),
        &config,
        &mut dir_count,
        &mut file_count,
    );

    // 3. 最終集計の出力
    println!();
    println!("\x1b[36m{} directories, {} files\x1b[0m", dir_count, file_count);
}

/// 引数を手動で解析 (軽量化のため標準ライブラリのみを使用)
fn parse_arguments(args: &[String], config: &mut TreeConfig) -> Result<(), String> {
    let mut i = 1;
    let mut path_set = false;

    while i < args.len() {
        let arg = &args[i];
        match arg.as_str() {
            "-h" | "--help" => {
                print_help();
                std::process::exit(0);
            }
            "-i" | "--icons" => {
                config.show_icons = true;
            }
            "-s" | "--sizes" => {
                config.show_sizes = true;
            }
            "-a" | "--all" => {
                config.show_hidden = true;
            }
            "-d" | "--depth" => {
                if i + 1 < args.len() {
                    let depth_str = &args[i + 1];
                    config.max_depth = depth_str
                        .parse::<usize>()
                        .map_err(|_| format!("無効な深度が指定されました: {}", depth_str))?;
                    i += 1;
                } else {
                    return Err("深度の値が指定されていません (-d <DEPTH>)".to_string());
                }
            }
            "-e" | "--exclude" => {
                if i + 1 < args.len() {
                    let excludes_str = &args[i + 1];
                    config.exclude_patterns = excludes_str
                        .split(',')
                        .map(|s| s.trim().to_string())
                        .filter(|s| !s.is_empty())
                        .collect();
                    i += 1;
                } else {
                    return Err("除外パターンが指定されていません (-e <PATTERNS>)".to_string());
                }
            }
            _ => {
                if arg.starts_with('-') {
                    return Err(format!("不明なオプションです: {}", arg));
                } else if !path_set {
                    config.target_path = PathBuf::from(arg);
                    path_set = true;
                } else {
                    return Err(format!("重複したターゲットパス指定です: {}", arg));
                }
            }
        }
        i += 1;
    }

    Ok(())
}

/// ヘルプメニューの出力
fn print_help() {
    println!(
        "\x1b[1mRust Tree CLI コマンド (Windows対応)\x1b[0m\n\
        \x1b[33m使用法:\x1b[0m\n  tree-rs [オプション] [ターゲットディレクトリ]\n\n\
        \x1b[33mオプション:\x1b[0m\n  \
          -h, --help           ヘルプメニューを表示\n  \
          -i, --icons          ファイルやフォルダにアイコン絵文字を付与\n  \
          -s, --sizes          ファイルサイズを表示 [サイズ]\n  \
          -a, --all            ドット(.)から始まる隠しファイルも表示\n  \
          -d, --depth <DEPTH>  探索する最大の階層の深さを指定 (例: -d 2)\n  \
          -e, --exclude <PAT>  除外するディレクトリ名を指定 (カンマ区切り、例: -e "target,node_modules")"
    );
}

/// ルート行のフォーマット
fn format_root_line(config: &TreeConfig) -> String {
    let folder_name = config
        .target_path
        .file_name()
        .and_then(|n| n.to_str())
        .unwrap_or(".");
    
    if config.show_icons {
        format!("\x1b[1;34m📁 {}\x1b[0m", folder_name)
    } else {
        format!("\x1b[1;34m{}\x1b[0m", folder_name)
    }
}

/// 再帰的なツリー構築コア処理
fn print_tree(
    dir: &Path,
    current_depth: usize,
    prefixes: &mut Vec<&str>,
    config: &TreeConfig,
    dir_count: &mut usize,
    file_count: &mut usize,
) {
    // 深度制限のチェック
    if config.max_depth > 0 && current_depth >= config.max_depth {
        return;
    }

    // ディレクトリのエントリを読み込む
    let entries = match fs::read_dir(dir) {
        Ok(e) => e,
        Err(_) => return, // 権限エラーなどはスキップ
    };

    // エントリを一度ベクターに詰める
    let mut valid_entries = Vec::new();
    for entry in entries {
        if let Ok(entry) = entry {
            let file_name = entry.file_name().to_string_lossy().into_owned();
            
            // 隠しファイルのフィルタ
            if file_name.starts_with('.') && !config.show_hidden {
                continue;
            }

            // 除外パターンのフィルタ
            let is_excluded = config.exclude_patterns.iter().any(|pattern| {
                file_name.eq_ignore_ascii_case(pattern)
            });
            if is_excluded {
                continue;
            }

            valid_entries.push(entry);
        }
    }

    // ソート処理 (ディレクトリを優先ソート)
    valid_entries.sort_by(|a, b| {
        let name_a = a.file_name();
        let name_b = b.file_name();
        
        let is_dir_a = a.path().is_dir();
        let is_dir_b = b.path().is_dir();

        if is_dir_a != is_dir_b {
            if is_dir_a { std::cmp::Ordering::Less } else { std::cmp::Ordering::Greater }
        } else {
            name_a.cmp(&name_b)
        }
    });

    let count = valid_entries.len();
    for (idx, entry) in valid_entries.iter().enumerate() {
        let is_last = idx == count - 1;
        let path = entry.path();
        let is_directory = path.is_dir();
        let file_name = entry.file_name().to_string_lossy().into_owned();

        // 1. インデント接頭辞の出力
        for pref in prefixes.iter() {
            print!("{}", pref);
        }

        // 2. ブランチ記号の決定
        let branch = if is_last { "└── " } else { "├── " };
        print!("{}", branch);

        // 3. アイコン絵文字の出力 (有効な場合)
        if config.show_icons {
            print!("{} ", get_icon_emoji(&file_name, is_directory));
        }

        // 4. 名前と各種メタ情報の出力
        if is_directory {
            *dir_count += 1;
            // ディレクトリは青字・太字
            print!("\x1b[1;34m{}\x1b[0m", file_name);
        } else {
            *file_count += 1;
            // 通常のファイル
            print!("{}", file_name);

            // ファイルサイズ表示
            if config.show_sizes {
                if let Ok(metadata) = entry.metadata() {
                    let size = metadata.len();
                    print!(" \x1b[90m[{}]\x1b[0m", format_byte_size(size));
                }
            }
        }
        println!();

        // ディレクトリの場合は再帰呼び出し
        if is_directory {
            let next_prefix = if is_last { "    " } else { "│   " };
            prefixes.push(next_prefix);
            print_tree(&path, current_depth + 1, prefixes, config, dir_count, file_count);
            prefixes.pop();
        }
    }
}

/// 拡張子やフォルダ名に応じた絵文字の取得
fn get_icon_emoji(name: &str, is_directory: bool) -> &'static str {
    if is_directory {
        match name.to_lowercase().as_str() {
            "src" => "📂",
            "tests" => "🧪",
            "target" => "🛠️",
            "node_modules" => "📦",
            ".git" => "🐙",
            _ => "📁",
        }
    } else {
        if name.starts_with(".env") {
            return "🔑";
        }
        if name == ".gitignore" {
            return "🙈";
        }
        
        let path = Path::new(name);
        match path.extension().and_then(|s| s.to_str()) {
            Some("rs") => "🦀",
            Some("toml") => "⚙️",
            Some("md") => "📝",
            Some("json") => "📄",
            Some("js") | Some("ts") => "🟨",
            Some("exe") => "🚀",
            _ => "📄",
        }
    }
}

/// バイト単位のファイルサイズを読みやすい形式に変換
fn format_byte_size(bytes: u64) -> String {
    if bytes < 1024 {
        format!("{} B", bytes)
    } else if bytes < 1024 * 1024 {
        format!("{:.1} KB", bytes as f64 / 1024.0)
    } else {
        format!("{:.1} MB", bytes as f64 / (1024.0 * 1024.0))
    }
}

/// Windows 10/11 コンソールで ANSI エスケープ処理を有効化する
#[cfg(windows)]
fn enable_ansi_support() {
    use std::ffi::OsStr;
    use std::os::windows::ffi::OsStrExt;
    use std::ptr::null_mut;

    // Windows APIを動的にロードしてコンソールのモードを書き換える
    // 依存関係を増やさないよう、libc や winapi クレートを使わずに実装
    type LPDWORD = *mut u32;
    type HANDLE = *mut std::ffi::c_void;

    const STD_OUTPUT_HANDLE: u32 = -11i32 as u32;
    const ENABLE_VIRTUAL_TERMINAL_PROCESSING: u32 = 0x0004;

    #[link(name = "kernel32")]
    extern "system" {
        fn GetStdHandle(nStdHandle: u32) -> HANDLE;
        fn GetConsoleMode(hConsoleHandle: HANDLE, lpMode: LPDWORD) -> i32;
        fn SetConsoleMode(hConsoleHandle: HANDLE, dwMode: u32) -> i32;
    }

    unsafe {
        let handle = GetStdHandle(STD_OUTPUT_HANDLE);
        if handle != null_mut() {
            let mut mode: u32 = 0;
            if GetConsoleMode(handle, &mut mode as LPDWORD) != 0 {
                SetConsoleMode(handle, mode | ENABLE_VIRTUAL_TERMINAL_PROCESSING);
            }
        }
    }
}
